A class holds an object whose access method is written to behave differently on the class than on an object, and it is also told the class's own name when the class is built. What does this program print?

class Tag:
    def __init__(self, name):
        self.name = name
    def __set_name__(self, owner, attr):
        self.owner = owner.__name__
    def __get__(self, obj, owner=None):
        if obj is None:
            return self.owner
        return f'<{self.name} of {obj.label}>'

class Card:
    tag = Tag('card')
    def __init__(self, label):
        self.label = label

print(Card.tag)
print(Card('A7').tag)
print(Card('A7').tag == '<card of A7>')

A decorator wraps a helper and announces the wrapped helper's name on the way in and on the way out, and the name left on the decorated helper is printed afterwards. What does this program print?

import functools

def timed(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kw):
        print('enter', fn.__name__)
        out = fn(*args, **kw)
        print('leave', fn.__name__)
        return out
    return wrapper

@timed
def work(n):
    return n * 2

print(work(3))
print(work.__name__)

A decorator wraps a helper and hands the wrapper back with nothing copied across, and the result, the name and the docstring are then printed in one call. What does this program print?

def timed(fn):
    def wrapper(*args, **kw):
        return fn(*args, **kw)
    return wrapper

@timed
def work(n):
    'doubling'
    return n * 2

r = work(3)
print(r, work.__name__, work.__doc__)

A decorator wraps a helper and copies the recorded details onto the wrapper, and the result, the name and the docstring are then printed together. What does this program print?

import functools

def logged(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kw):
        return fn(*args, **kw)
    return wrapper

@logged
def work(n):
    'doubling the input'
    return n * 2

print(work(3), work.__name__, work.__doc__)

Two decorators are stacked on one helper, each announcing when it is entered and left, and the helper itself prints as it runs. What does this program print?

def outer(fn):
    def w(*a):
        print('outer in')
        r = fn(*a)
        print('outer out')
        return r
    return w

def inner(fn):
    def w(*a):
        print('inner in')
        r = fn(*a)
        print('inner out')
        return r
    return w

@outer
@inner
def work():
    print('work')
    return 'done'

print(work())

A decorator factory takes a label, announces the label as it is built, and each call through the wrapper announces the label again. What does this program print?

import functools

def tag(label):
    print('making', label)
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*a, **k):
            print('call', label)
            return fn(*a, **k)
        return wrapper
    return deco

@tag('alpha')
def work(n):
    return n + 1

print(work(1))
print(work.__name__)

A generator is built once and then walked by two loops in turn, and the report is the whole printout of the program. What does this program actually print?

def gen():
    yield 'a'
    yield 'b'

shared = gen()
for x in shared:
    print('first', x)
for x in shared:
    print('second', x)
print('done')

A decorator wraps a helper and hands the wrapper back without copying anything, and the program then reads the name and the docstring off the decorated name. What does this program actually print?

def logged(fn):
    def wrapper(*a, **k):
        return fn(*a, **k)
    return wrapper

